/**
 * @summary Export waitlist as CSV
 */
export const getExportWaitlistUrl = (params: ExportWaitlistParams) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/waitlist/export?${stringifiedParams}`
    : `/api/waitlist/export`;
};

export const exportWaitlist = async (
  params: ExportWaitlistParams,
  options?: RequestInit,
): Promise<string> => {
  return customFetch<string>(getExportWaitlistUrl(params), {
    ...options,
    method: "GET",
  });
};

export const getExportWaitlistQueryKey = (params?: ExportWaitlistParams) => {
  return [`/api/waitlist/export`, ...(params ? [params] : [])] as const;
};

export const getExportWaitlistQueryOptions = <
  TData = Awaited<ReturnType<typeof exportWaitlist>>,
  TError = ErrorType<ErrorResponse>,
>(
  params: ExportWaitlistParams,
  options?: {
    query?: UseQueryOptions<
      Awaited<ReturnType<typeof exportWaitlist>>,
      TError,
      TData
    >;
    request?: SecondParameter<typeof customFetch>;
  },
) => {
  const { query: queryOptions, request: requestOptions } = options ?? {};

  const queryKey = queryOptions?.queryKey ?? getExportWaitlistQueryKey(params);

  const queryFn: QueryFunction<Awaited<ReturnType<typeof exportWaitlist>>> = ({
    signal,
  }) => exportWaitlist(params, { signal, ...requestOptions });

  return { queryKey, queryFn, ...queryOptions } as UseQueryOptions<
    Awaited<ReturnType<typeof exportWaitlist>>,
    TError,
    TData
  > & { queryKey: QueryKey };
};

export type ExportWaitlistQueryResult = NonNullable<
  Awaited<ReturnType<typeof exportWaitlist>>
>;
export type ExportWaitlistQueryError = ErrorType<ErrorResponse>;

/**
 * @summary Export waitlist as CSV
 */

export function useExportWaitlist<
  TData = Awaited<ReturnType<typeof exportWaitlist>>,
  TError = ErrorType<ErrorResponse>,
>(
  params: ExportWaitlistParams,
  options?: {
    query?: UseQueryOptions<
      Awaited<ReturnType<typeof exportWaitlist>>,
      TError,
      TData
    >;
    request?: SecondParameter<typeof customFetch>;
  },
): UseQueryResult<TData, TError> & { queryKey: QueryKey } {
  const queryOptions = getExportWaitlistQueryOptions(params, options);

  const query = useQuery(queryOptions) as UseQueryResult<TData, TError> & {
    queryKey: QueryKey;
  };

  return { ...query, queryKey: queryOptions.queryKey };
}
